<template>
  <section>
    <div class="admin-section-head"><div><p class="eyebrow">Collections</p><h2>内容模块</h2></div></div>
    <div class="subtabs"><button v-for="tab in tabs" :key="tab.value" :class="{ active: active === tab.value }" @click="active = tab.value">{{ tab.label }}<span v-if="tab.value === 'guestbook' && pendingCount">{{ pendingCount }}</span></button></div>
    <AdminNotice :message="notice" :success="success" @close="notice = ''" />

    <section v-if="active === 'library'" class="module-panel">
      <form class="card-form" @submit.prevent="createLibrary"><div class="form-grid three"><div class="field"><label>类型</label><select v-model="libraryDraft.item_type"><option value="book">书籍</option><option value="movie">电影</option><option value="anime">动漫</option></select></div><div class="field"><label>名称</label><input v-model="libraryDraft.title" required /></div><div class="field"><label>状态</label><select v-model="libraryDraft.status"><option value="wishlist">想看</option><option value="reading">进行中</option><option value="completed">已完成</option></select></div></div><div class="form-grid two"><div class="field"><label>豆瓣 / 外部链接</label><input v-model="libraryDraft.external_url" type="url" /></div><div class="field"><label>评分（0-10）</label><input v-model.number="libraryDraft.rating" type="number" min="0" max="10" step="0.5" /></div></div><div class="field"><label>简短感想</label><textarea v-model="libraryDraft.note" rows="3"></textarea></div><div class="image-row"><div class="field"><label>封面地址</label><input v-model="libraryDraft.cover_image" /></div><ImageUploader compact label="上传封面" @uploaded="libraryDraft.cover_image = $event.url" /></div><button class="primary-button" :disabled="isBusy('create:library')">{{ isBusy('create:library') ? "添加中…" : "添加到图书馆" }}</button></form>
      <form class="library-filters" @submit.prevent="applyLibraryFilters">
        <div class="field filter-keyword"><label>搜索收藏</label><input v-model.trim="libraryFilterDraft.keyword" placeholder="输入名称或感想" /></div>
        <div class="field"><label>类型</label><select v-model="libraryFilterDraft.item_type"><option value="">全部类型</option><option value="book">书籍</option><option value="movie">电影</option><option value="anime">动漫</option></select></div>
        <div class="field"><label>状态</label><select v-model="libraryFilterDraft.status"><option value="">全部状态</option><option value="wishlist">想看</option><option value="reading">进行中</option><option value="completed">已完成</option></select></div>
        <button class="primary-button" :disabled="libraryLoading">{{ libraryLoading ? "读取中…" : "筛选" }}</button><button class="secondary-button" type="button" :disabled="libraryLoading" @click="resetLibraryFilters">重置</button>
        <span class="result-count">共 {{ libraryPagination.total }} 项</span>
      </form>
      <div v-if="libraryLoading" class="admin-empty">正在读取图书馆…</div>
      <div v-else-if="!library.length" class="admin-empty">没有找到符合条件的内容。</div>
      <div v-else class="collection-grid">
        <article v-for="item in library" :key="item.id" :class="{ editing: editingLibraryId === item.id }">
          <form v-if="editingLibraryId === item.id" class="library-edit-form" @submit.prevent="saveItem(item)">
            <div class="form-grid three"><div class="field"><label>类型</label><select v-model="libraryEditDraft.item_type"><option value="book">书籍</option><option value="movie">电影</option><option value="anime">动漫</option></select></div><div class="field"><label>名称</label><input v-model="libraryEditDraft.title" required /></div><div class="field"><label>状态</label><select v-model="libraryEditDraft.status"><option value="wishlist">想看</option><option value="reading">进行中</option><option value="completed">已完成</option></select></div></div>
            <div class="form-grid three"><div class="field"><label>评分（0-10）</label><input v-model.number="libraryEditDraft.rating" type="number" min="0" max="10" step="0.5" /></div><div class="field"><label>完成日期</label><input v-model="libraryEditDraft.finished_at" type="date" /></div><div class="field"><label>排序值</label><input v-model.number="libraryEditDraft.sort_order" type="number" /></div></div>
            <div class="field"><label>豆瓣 / 外部链接</label><input v-model="libraryEditDraft.external_url" type="url" /></div>
            <div class="field"><label>简短感想</label><textarea v-model="libraryEditDraft.note" rows="4"></textarea></div>
            <div class="image-row"><div class="field"><label>封面地址</label><input v-model="libraryEditDraft.cover_image" /></div><ImageUploader compact label="重新上传封面" @uploaded="libraryEditDraft.cover_image = $event.url" /></div>
            <div class="edit-actions"><button class="primary-button" :disabled="isBusy(`save:library:${item.id}`)">{{ isBusy(`save:library:${item.id}`) ? "保存中…" : "保存修改" }}</button><button type="button" class="secondary-button" :disabled="isBusy(`save:library:${item.id}`)" @click="cancelLibraryEdit">取消</button></div>
          </form>
          <template v-else>
            <img v-if="item.cover_image" :src="item.cover_image" :alt="item.title" />
            <div class="collection-summary"><small>{{ typeLabel(item.item_type) }} · {{ libraryStatusLabel(item.status) }}</small><strong>{{ item.title }}</strong><p v-if="item.note">{{ item.note }}</p><span v-if="item.rating !== null && item.rating !== undefined">{{ item.rating }}/10</span></div>
            <button type="button" @click="startLibraryEdit(item)">编辑</button><button type="button" class="remove" :disabled="isBusy(`delete:library:${item.id}`)" @click="remove('library', item)">{{ isBusy(`delete:library:${item.id}`) ? "删除中…" : "删除" }}</button>
          </template>
        </article>
      </div>
      <AdminPagination :page="libraryPagination.page" :total-pages="libraryPagination.totalPages" :loading="libraryLoading" label="图书馆分页" @change="loadLibrary" />
    </section>

    <section v-else-if="active === 'albums'" class="module-panel">
      <form class="inline-create" @submit.prevent="createAlbum"><div class="field"><label>相册名称</label><input v-model="albumDraft.title" required /></div><div class="field grow"><label>相册说明</label><input v-model="albumDraft.description" /></div><button class="primary-button" :disabled="isBusy('create:albums')">{{ isBusy('create:albums') ? "创建中…" : "创建相册" }}</button></form>
      <div class="album-admin-list"><article v-for="album in albums" :key="album.id"><div class="album-head"><div><h3>{{ album.title }}</h3><p>{{ album.description || "没有说明" }}</p></div><button class="danger-button" :disabled="isBusy(`delete:albums:${album.id}`)" @click="remove('albums', album)">{{ isBusy(`delete:albums:${album.id}`) ? "删除中…" : "删除相册" }}</button></div><ImageUploader multiple compact label="向这个相册添加照片" @uploaded="addPhoto(album, $event)" /><div class="album-photos"><div v-for="photo in album.photos" :key="photo.id"><img :src="photo.thumbnail_url || photo.image_url" :alt="photo.caption || album.title" /><button :disabled="isBusy(`photo:delete:${photo.id}`)" @click="removePhoto(album, photo)">×</button></div></div></article></div>
    </section>

    <section v-else-if="active === 'guestbook'" class="module-panel">
      <div v-if="!messages.length" class="admin-empty">还没有留言。</div><div class="message-admin-list"><article v-for="message in messages" :key="message.id"><div class="message-head"><strong>{{ message.nickname }}</strong><span class="post-tag">{{ message.message_type === "wish" ? "许愿" : "留言" }}</span><time>{{ formatDate(message.created_at) }}</time><select v-model="message.status"><option value="pending">待审核</option><option value="approved">公开</option><option value="hidden">隐藏</option></select></div><p>{{ message.content }}</p><div class="field"><label>站长回复</label><textarea v-model="message.admin_reply" rows="2"></textarea></div><div class="item-actions"><button class="primary-button" :disabled="isBusy(`save:guestbook:${message.id}`)" @click="saveMessage(message)">{{ isBusy(`save:guestbook:${message.id}`) ? "保存中…" : "保存审核结果" }}</button><button class="danger-button" :disabled="isBusy(`delete:guestbook:${message.id}`)" @click="remove('guestbook', message)">{{ isBusy(`delete:guestbook:${message.id}`) ? "删除中…" : "删除" }}</button></div></article></div>
    </section>


  </section>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from "vue";
import AdminNotice from "./AdminNotice.vue";
import AdminPagination from "./AdminPagination.vue";
import ImageUploader from "../ImageUploader.vue";
import { addAlbumPhoto, createAdminResource, deleteAdminResource, deleteAlbumPhoto, getAdminLibrary, getAdminResource, updateAdminResource } from "../../api/content";
const tabs = [{ value: "library", label: "图书馆" }, { value: "albums", label: "相册" }, { value: "guestbook", label: "留言与许愿审核" }];
const active = ref("library"); const library = ref([]); const albums = ref([]); const messages = ref([]); const notice = ref(""); const success = ref(false);
const editingLibraryId = ref(null);
const libraryLoading = ref(true);
const busyKeys = reactive(new Set());
const libraryDraft = reactive({ item_type: "book", title: "", cover_image: "", external_url: "", status: "completed", rating: null, note: "", finished_at: null, sort_order: 0 }); const albumDraft = reactive({ title: "", description: "", cover_image: "", sort_order: 0 });
const libraryEditDraft = reactive({ item_type: "book", title: "", cover_image: "", external_url: "", status: "completed", rating: null, note: "", finished_at: "", sort_order: 0 });
const libraryFilterDraft = reactive({ keyword: "", item_type: "", status: "" });
const libraryFilters = reactive({ keyword: "", item_type: "", status: "" });
const libraryPagination = reactive({ page: 1, pageSize: 12, total: 0, totalPages: 0 });
const pendingCount = computed(() => messages.value.filter((item) => item.status === "pending").length);
function typeLabel(value) { return ({ book: "书籍", movie: "电影", anime: "动漫" })[value]; }
function libraryStatusLabel(value) { return ({ wishlist: "想看", reading: "进行中", completed: "已完成" })[value] || value; }
function formatDate(value) { return new Date(value).toLocaleString("zh-CN"); }
function isBusy(key) { return busyKeys.has(key); }
async function runAction(key, action, fallbackMessage) { if (busyKeys.has(key)) return null; busyKeys.add(key); notice.value = ""; try { return await action(); } catch (error) { success.value = false; notice.value = error.response?.data?.detail || fallbackMessage; return null; } finally { busyKeys.delete(key); } }
async function loadLibrary(page = 1) { libraryLoading.value = true; try { const { data } = await getAdminLibrary({ page, page_size: libraryPagination.pageSize, keyword: libraryFilters.keyword || undefined, item_type: libraryFilters.item_type || undefined, status: libraryFilters.status || undefined }); if (!data.items.length && data.total > 0 && page > data.total_pages) { await loadLibrary(data.total_pages); return; } library.value = data.items; Object.assign(libraryPagination, { page: data.page, pageSize: data.page_size, total: data.total, totalPages: data.total_pages }); } catch (error) { library.value = []; success.value = false; notice.value = error.response?.data?.detail || "图书馆加载失败。"; } finally { libraryLoading.value = false; } }
function applyLibraryFilters() { Object.assign(libraryFilters, libraryFilterDraft); editingLibraryId.value = null; loadLibrary(1); }
function resetLibraryFilters() { Object.assign(libraryFilterDraft, { keyword: "", item_type: "", status: "" }); Object.assign(libraryFilters, libraryFilterDraft); editingLibraryId.value = null; loadLibrary(1); }
async function createLibrary() { const itemType = libraryDraft.item_type; const created = await runAction("create:library", async () => (await createAdminResource("library", { ...libraryDraft, rating: libraryDraft.rating === "" ? null : libraryDraft.rating, cover_image: libraryDraft.cover_image || null, external_url: libraryDraft.external_url || null, note: libraryDraft.note || null })).data, "创建失败。"); if (!created) return; Object.assign(libraryDraft, { item_type: "book", title: "", cover_image: "", external_url: "", status: "completed", rating: null, note: "", finished_at: null, sort_order: 0 }); Object.assign(libraryFilterDraft, { keyword: "", item_type: itemType, status: "" }); Object.assign(libraryFilters, libraryFilterDraft); success.value = true; notice.value = "内容已添加到图书馆。"; await loadLibrary(1); }
function startLibraryEdit(item) { editingLibraryId.value = item.id; Object.assign(libraryEditDraft, { item_type: item.item_type, title: item.title, cover_image: item.cover_image || "", external_url: item.external_url || "", status: item.status, rating: item.rating, note: item.note || "", finished_at: item.finished_at || "", sort_order: item.sort_order || 0 }); }
function cancelLibraryEdit() { editingLibraryId.value = null; }
async function saveItem(item) { const saved = await save("library", item, { ...libraryEditDraft, cover_image: libraryEditDraft.cover_image || null, external_url: libraryEditDraft.external_url || null, rating: libraryEditDraft.rating === "" ? null : libraryEditDraft.rating, note: libraryEditDraft.note || null, finished_at: libraryEditDraft.finished_at || null }); if (saved) { editingLibraryId.value = null; await loadLibrary(libraryPagination.page); } }
async function createAlbum() { const data = await runAction("create:albums", async () => (await createAdminResource("albums", albumDraft)).data, "相册创建失败。"); if (!data) return; albums.value.unshift(data); Object.assign(albumDraft, { title: "", description: "", cover_image: "", sort_order: 0 }); success.value = true; notice.value = "相册已创建。"; }
async function addPhoto(album, asset) { try { const { data } = await addAlbumPhoto(album.id, { media_id: asset.id, image_url: asset.url, thumbnail_url: asset.thumbnail_url, caption: "", sort_order: album.photos.length }); album.photos.push(data); if (!album.cover_image) { album.cover_image = asset.thumbnail_url || asset.url; await updateAdminResource("albums", album.id, { cover_image: album.cover_image }); } success.value = true; notice.value = "照片已加入相册。"; } catch (error) { success.value = false; notice.value = error.response?.data?.detail || "照片加入相册失败。"; } }
async function removePhoto(album, photo) { const removed = await runAction(`photo:delete:${photo.id}`, async () => { await deleteAlbumPhoto(photo.id); return true; }, "照片删除失败。"); if (!removed) return; album.photos = album.photos.filter((item) => item.id !== photo.id); success.value = true; notice.value = "照片已删除。"; }
async function saveMessage(item) { await save("guestbook", item, { status: item.status, admin_reply: item.admin_reply || null }); }
async function save(resource, item, payload) { const data = await runAction(`save:${resource}:${item.id}`, async () => (await updateAdminResource(resource, item.id, payload)).data, "保存失败。"); if (!data) return false; Object.assign(item, data); success.value = true; notice.value = "内容已保存。"; return true; }
async function remove(resource, item) { if (!window.confirm("确定删除这条内容？")) return; const removed = await runAction(`delete:${resource}:${item.id}`, async () => { await deleteAdminResource(resource, item.id); return true; }, "删除失败。"); if (!removed) return; if (resource === "library") { const targetPage = library.value.length === 1 && libraryPagination.page > 1 ? libraryPagination.page - 1 : libraryPagination.page; editingLibraryId.value = null; await loadLibrary(targetPage); } else { const map = { albums, guestbook: messages }; map[resource].value = map[resource].value.filter((entry) => entry.id !== item.id); } success.value = true; notice.value = "内容已删除。"; }
onMounted(async () => { const resources = ["albums", "guestbook"]; const results = await Promise.allSettled([...resources.map(getAdminResource), loadLibrary()]); const refs = [albums, messages]; results.slice(0, resources.length).forEach((result, index) => { if (result.status === "fulfilled") refs[index].value = result.value.data; else { notice.value = "部分内容加载失败，请刷新重试。"; success.value = false; } }); });
</script>

<style scoped>
.admin-section-head { margin-bottom: 22px; }.admin-section-head h2 { margin: 0; font: 500 32px Georgia, "Songti SC", serif; }.subtabs { display: flex; flex-wrap: wrap; gap: 7px; margin-bottom: 20px; }.subtabs button { padding: 9px 14px; border: 1px solid var(--line); border-radius: 999px; background: #fff; }.subtabs button.active { color: #fff; border-color: var(--rose-600); background: var(--rose-600); }.subtabs span { margin-left: 6px; padding: 1px 5px; border-radius: 999px; color: var(--rose-700); background: #fff; font-size: 10px; }.module-panel { display: grid; gap: 20px; }.inline-create, .card-form { padding: 18px; display: flex; align-items: end; gap: 10px; border: 1px solid var(--line); border-radius: 15px; background: rgba(255,255,255,.72); }.card-form { display: grid; }.grow { flex: 1; }.form-grid { display: grid; gap: 12px; }.form-grid.two { grid-template-columns: 1fr 1fr; }.form-grid.three { grid-template-columns: repeat(3, 1fr); }.image-row { display: grid; grid-template-columns: 1fr 240px; gap: 10px; align-items: end; }.edit-actions { display: flex; gap: 8px; align-items: center; }.library-filters { padding: 14px; display: grid; grid-template-columns: minmax(220px, 1fr) 150px 150px auto auto auto; gap: 10px; align-items: end; border: 1px solid var(--line); border-radius: 14px; background: rgba(255,255,255,.72); }.library-filters input, .library-filters select { width: 100%; }.result-count { align-self: center; color: var(--muted); font-size: 12px; white-space: nowrap; }.remove { color: #a84d4d !important; }.collection-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; }.collection-grid article { padding: 10px; display: grid; grid-template-columns: 64px 1fr auto auto; gap: 10px; align-items: center; border: 1px solid var(--line); border-radius: 12px; background: #fff; }.collection-grid article.editing { grid-column: 1 / -1; display: block; padding: 18px; }.collection-grid img { width: 64px; height: 84px; object-fit: cover; border-radius: 6px; }.collection-summary { min-width: 0; display: grid; gap: 5px; }.collection-summary strong { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.collection-summary p { margin: 0; display: -webkit-box; overflow: hidden; color: var(--muted); font-size: 11px; line-height: 1.5; -webkit-box-orient: vertical; -webkit-line-clamp: 2; }.collection-summary span { color: var(--muted-strong); font-size: 11px; }.library-edit-form { display: grid; gap: 14px; }.collection-grid input, .collection-grid select { min-width: 0; padding: 6px; border: 1px solid var(--line); border-radius: 7px; }.collection-grid small { color: var(--rose-600); }.album-admin-list, .message-admin-list, .album-admin-list > article, .message-admin-list > article { padding: 18px; border: 1px solid var(--line); border-radius: 15px; background: #fff; }.album-head, .message-head, .item-actions { display: flex; align-items: center; justify-content: space-between; gap: 10px; }.album-head h3 { margin: 0; }.album-head p { margin: 4px 0 0; color: var(--muted); font-size: 12px; }.album-photos { display: grid; grid-template-columns: repeat(6, 1fr); gap: 7px; margin-top: 12px; }.album-photos div { position: relative; aspect-ratio: 1; }.album-photos img { width: 100%; height: 100%; object-fit: cover; border-radius: 7px; }.album-photos button { position: absolute; top: 3px; right: 3px; border: 0; border-radius: 50%; color: #fff; background: rgba(0,0,0,.55); }.message-head time { flex: 1; color: var(--muted); font-size: 11px; }.message-head select { padding: 6px; border: 1px solid var(--line); border-radius: 8px; }.message-admin-list article > p { color: var(--muted-strong); line-height: 1.75; }.item-actions { justify-content: flex-start; margin-top: 10px; }.admin-empty { padding: 24px; color: var(--muted); text-align: center; }
@media (max-width: 1000px) { .library-filters { grid-template-columns: 1fr 1fr 1fr; }.result-count { justify-self: end; } }
@media (max-width: 900px) {  }
@media (max-width: 800px) { .inline-create { display: grid; }.form-grid.two, .form-grid.three, .image-row, .collection-grid, .library-filters { grid-template-columns: 1fr; }.library-filters .primary-button, .library-filters .secondary-button { width: 100%; }.result-count { justify-self: start; }.collection-grid article { grid-template-columns: 64px 1fr; }.collection-grid article.editing { grid-column: auto; }.album-photos { grid-template-columns: repeat(3, 1fr); } }
@media (max-width: 560px) {  }
</style>
